import unittest

from solution import process_inbox


class ProcessInboxTests(unittest.TestCase):
    def test_processing_order_filtering_and_exact_result_shape(self):
        parse_calls = []
        assess_calls = []

        def parse(raw):
            parse_calls.append(raw)
            return {"id": raw, "nested": [raw]}

        def assess(parsed):
            assess_calls.append(parsed["id"])
            return parsed["id"] != "safe"

        result = process_inbox(
            [("ignored.txt", "ignored"), ("a.packet", "one"), ("b.packet", "safe"), ("c.packet", "two")],
            parse,
            assess,
        )
        self.assertEqual(set(result), {"accepted", "activity", "errors"})
        self.assertEqual(result["activity"], (("one", "a.packet"), ("safe", "b.packet"), ("two", "c.packet")))
        self.assertEqual(result["errors"], ())
        self.assertEqual([item["id"] for item in result["accepted"]], ["one", "two"])
        self.assertEqual(parse_calls, ["one", "safe", "two"])
        self.assertEqual(assess_calls, ["one", "safe", "two"])
        for value in result.values():
            self.assertIsInstance(value, tuple)

    def test_known_and_accepted_duplicates_are_skipped(self):
        assessed = []

        def parse(raw):
            return {"id": raw}

        def assess(parsed):
            assessed.append(parsed["id"])
            return True

        result = process_inbox(
            [("a.packet", "known"), ("b.packet", "new"), ("c.packet", "new")],
            parse,
            assess,
            known_ids=(value for value in ["known"]),
        )
        self.assertEqual(result["activity"], (("known", "a.packet"), ("new", "b.packet"), ("new", "c.packet")))
        self.assertEqual(assessed, ["new"])
        self.assertEqual(result["accepted"], ({"id": "new"},))

    def test_safe_duplicate_may_be_assessed_again_and_only_exact_true_accepts(self):
        returns = iter([False, 1, True])
        calls = []

        def parse(raw):
            return {"id": raw}

        def assess(parsed):
            calls.append(parsed["id"])
            return next(returns)

        result = process_inbox(
            [("a.packet", "same"), ("b.packet", "same"), ("c.packet", "same")],
            parse,
            assess,
        )
        self.assertEqual(calls, ["same", "same", "same"])
        self.assertEqual(result["accepted"], ({"id": "same"},))

    def test_errors_continue_and_activity_occurs_after_valid_parse(self):
        def parse(raw):
            if raw == "parse-error":
                raise RuntimeError("cannot parse")
            if raw == "bad-shape":
                return []
            if raw == "bad-id":
                return {"id": " "}
            return {"id": raw}

        def assess(parsed):
            if parsed["id"] == "assessment-error":
                raise LookupError("cannot assess")
            return True

        result = process_inbox(
            [
                ("a.packet", "parse-error"),
                ("b.packet", "bad-shape"),
                ("c.packet", "bad-id"),
                ("d.packet", "assessment-error"),
                ("e.packet", "ok"),
            ],
            parse,
            assess,
        )
        self.assertEqual(result["activity"], (("assessment-error", "d.packet"), ("ok", "e.packet")))
        self.assertEqual(result["accepted"], ({"id": "ok"},))
        self.assertEqual([name for name, _ in result["errors"]], ["a.packet", "b.packet", "c.packet", "d.packet"])
        self.assertEqual(result["errors"][0], ("a.packet", "cannot parse"))
        self.assertEqual(result["errors"][3], ("d.packet", "cannot assess"))

    def test_deep_copy_and_no_alias_leaks(self):
        parsed = {"id": "x", "nested": {"values": [1]}}

        result = process_inbox([("x.packet", parsed)], lambda raw: raw, lambda value: True)
        parsed["nested"]["values"].append(2)
        self.assertEqual(result["accepted"][0], {"id": "x", "nested": {"values": [1]}})
        result["accepted"][0]["nested"]["values"].append(3)

        again = process_inbox([("x.packet", parsed)], lambda raw: raw, lambda value: True)
        self.assertEqual(again["accepted"][0]["nested"]["values"], [1, 2])

    def test_prevalidation_happens_before_entries_are_consumed(self):
        consumed = []

        def entries():
            consumed.append(True)
            yield ("x.packet", "x")

        with self.assertRaises(TypeError):
            process_inbox(entries(), None, lambda value: True)
        self.assertEqual(consumed, [])
        with self.assertRaises(TypeError):
            process_inbox(entries(), lambda value: value, None)
        self.assertEqual(consumed, [])

        for known in (["ok", ""], ["ok", "  "], ["ok", 3]):
            with self.assertRaises(ValueError):
                process_inbox(entries(), lambda value: value, lambda value: True, known)
            self.assertEqual(consumed, [])


if __name__ == "__main__":
    unittest.main()

